async function V_CLIMB_UP(dir = P.UP, obj = false) {
  let x = 0, tx = 0;
  if (obj && !(g.PRSO == ROOMS)) {
    obj = g.PRSO;
  }
  if (tx = getPropAddr(g.HERE, dir)) {
    if (obj) {
      x = propSize(tx);
      if ((x == NEXIT) || ((x == CEXIT || x == DEXIT || x == UEXIT) && !(await GLOBAL_IN$(g.PRSO, getb(tx, 0))))) {
        tell("The ", D(obj), " do");
        if (!(obj == STAIRS)) {
          tell("es");
        }
        tell("n't lead ");
        if (dir == P.UP) {
          tell("up");
        } else {
          tell("down");
        }
        tell("ward.\n");
        return true;
      }
    }
    await DO_WALK(dir);
    return true;
  } else if (obj && (await ZMEMQ(W.WALL, x = getPropAddr(g.PRSO, P.SYNONYM), propSize(x)))) {
    tell("Climbing the walls is to no avail.\n");
    return true;
  } else if (!(g.HERE == PATH) && (obj == false || obj == TREE) && (await GLOBAL_IN$(TREE, g.HERE))) {
    tell("There are no climbable trees here.\n");
    return true;
  } else if (obj == false || obj == ROOMS) {
    tell("You can't go that way.\n");
    return true;
  } else {
    tell("You can't do that!\n");
    return true;
  }
}

