async function V_ECHO() {
  let lst = 0, max = 0, ech = 0, cnt = 0;
  if (getb(g.P_LEXV, P_LEXWORDS) > 0) {
    lst = g.P_LEXV + (getb(g.P_LEXV, P_LEXWORDS) * P_WORDLEN);
    max = (getb(lst, 0) + getb(lst, 1)) - 1;
    for (;;) {
      if ((ech = ech + 1) > 2) {
        tell("...\n");
        return true;
      } else {
        cnt = getb(lst, 1) - 1;
        loop2: for (;;) {
          if ((cnt = cnt + 1) > max) {
            break loop2;
          } else {
            printC(getb(g.P_INBUF, cnt));
          }
        }
        tell(" ");
      }
    }
  } else {
    tell("echo echo ...\n");
    return true;
  }
}

