async function V_WALK() {
  let pt = 0, pts = 0, str = 0, obj = 0, rm = 0;
  if (!g.P_WALK_DIR) {
    await PERFORM(V.WALK_TO, g.PRSO);
    return true;
  } else if (pt = getPropAddr(g.HERE, g.PRSO)) {
    if (eq(pts = propSize(pt), UEXIT)) {
      return await GOTO(getb(pt, REXIT));
    } else if (pts == NEXIT) {
      tell(S(get(pt, NEXITSTR)), "\n");
      return M_FATAL;
    } else if (pts == FEXIT) {
      if (rm = await apply(get(pt, FEXITFCN))) {
        return await GOTO(rm);
      } else if (await NULL_F()) {
        return false;
      } else {
        return M_FATAL;
      }
    } else if (pts == CEXIT) {
      if (globalValue(getb(pt, CEXITFLAG))) {
        return await GOTO(getb(pt, REXIT));
      } else if (str = get(pt, CEXITSTR)) {
        tell(S(str), "\n");
        return M_FATAL;
      } else {
        tell("You can't go that way.\n");
        return M_FATAL;
      }
    } else if (pts == DEXIT) {
      if (hasFlag(obj = getb(pt, DEXITOBJ), OPENBIT)) {
        return await GOTO(getb(pt, REXIT));
      } else if (str = get(pt, DEXITSTR)) {
        tell(S(str), "\n");
        return M_FATAL;
      } else {
        tell("The ", D(obj), " is closed.\n");
        await THIS_IS_IT(obj);
        return M_FATAL;
      }
    } else {
      return false;
    }
  } else if (!g.LIT && (80 > random(100)) && (g.WINNER == ADVENTURER) && !(hasFlag(g.HERE, NONLANDBIT))) {
    if (g.SPRAYED$) {
      tell("There are odd noises in the darkness, and there is no exit in that direction.\n");
      return M_FATAL;
    } else if (await NULL_F()) {
      return false;
    } else {
      return (await JIGS_UP("Oh, no! You have walked into the slavering fangs of a lurking grue!"));
    }
  } else {
    tell("You can't go that way.\n");
    return M_FATAL;
  }
}

