async function GRATE_FUNCTION() {
  if (isVerb(V.OPEN) && (g.PRSI == KEYS)) {
    await PERFORM(V.UNLOCK, GRATE, KEYS);
    return true;
  } else if (isVerb(V.LOCK)) {
    if (g.HERE == GRATING_ROOM) {
      g.GRUNLOCK = false;
      tell("The grate is locked.\n");
      return true;
    } else if (g.HERE == GRATING_CLEARING) {
      tell("You can't lock it from this side.\n");
      return true;
    } else {
      return false;
    }
  } else if (isVerb(V.UNLOCK) && (g.PRSO == GRATE)) {
    if ((g.HERE == GRATING_ROOM) && (g.PRSI == KEYS)) {
      g.GRUNLOCK = true;
      tell("The grate is unlocked.\n");
      return true;
    } else if ((g.HERE == GRATING_CLEARING) && (g.PRSI == KEYS)) {
      tell("You can't reach the lock from here.\n");
      return true;
    } else {
      tell("Can you unlock a grating with a ", D(g.PRSI), "?\n");
      return true;
    }
  } else if (isVerb(V.PICK)) {
    tell("You can't pick the lock.\n");
    return true;
  } else if (isVerb(V.OPEN, V.CLOSE)) {
    if (g.GRUNLOCK) {
      (await OPEN_CLOSE(GRATE, (g.HERE == CLEARING ? "The grating opens." : "The grating opens to reveal trees above you."), "The grating is closed."));
      if (hasFlag(GRATE, OPENBIT)) {
        if (!(g.HERE == CLEARING) && !g.GRATE_REVEALED) {
          tell("A pile of leaves falls onto your head and to the ground.\n");
          g.GRATE_REVEALED = true;
          move(LEAVES, g.HERE);
        }
        return setFlag(GRATING_ROOM, ONBIT);
      } else {
        return clearFlag(GRATING_ROOM, ONBIT);
      }
    } else {
      tell("The grating is locked.\n");
      return true;
    }
  } else if (isVerb(V.PUT) && (g.PRSI == GRATE)) {
    if (getProp(g.PRSO, P.SIZE) > 20) {
      tell("It won't fit through the grating.\n");
      return true;
    } else {
      move(g.PRSO, GRATING_ROOM);
      tell("The ", D(g.PRSO), " goes through the grating into the darkness below.\n");
      return true;
    }
  } else {
    return false;
  }
}

