async function MIRROR_MIRROR() {
  let rm2 = MIRROR_ROOM_2, l1 = 0, l2 = 0, n_ = 0;
  if (!g.MIRROR_MUNG && isVerb(V.RUB)) {
    if (g.PRSI && !(g.PRSI == HANDS)) {
      tell("You feel a faint tingling transmitted through the ", D(g.PRSI), ".\n");
      return true;
    }
    if (g.HERE == rm2) {
      rm2 = MIRROR_ROOM_1;
    }
    l1 = first(g.HERE);
    l2 = first(rm2);
    loop1: for (;;) {
      if (!l1) {
        break loop1;
      }
      n_ = next(l1);
      move(l1, rm2);
      l1 = n_;
    }
    loop2: for (;;) {
      if (!l2) {
        break loop2;
      }
      n_ = next(l2);
      move(l2, g.HERE);
      l2 = n_;
    }
    await GOTO(rm2, false);
    tell("There is a rumble from deep within the earth and the room shakes.\n");
    return true;
  } else if (isVerb(V.LOOK_INSIDE, V.EXAMINE)) {
    if (g.MIRROR_MUNG) {
      tell("The mirror is broken into many pieces.");
    } else {
      tell("There is an ugly person staring back at you.");
    }
    return crlf();
  } else if (isVerb(V.TAKE)) {
    tell("The mirror is many times your size. Give up.\n");
    return true;
  } else if (isVerb(V.MUNG, V.THROW, V.ATTACK)) {
    if (g.MIRROR_MUNG) {
      tell("Haven't you done enough damage already?\n");
      return true;
    } else {
      g.MIRROR_MUNG = true;
      g.LUCKY = false;
      tell("You have broken the mirror. I hope you have a seven years' supply of good luck handy.\n");
      return true;
    }
  } else {
    return false;
  }
}

