async function MATCH_FUNCTION() {
  let cnt = 0;
  if (isVerb(V.LAMP_ON, V.BURN) && (g.PRSO == MATCH)) {
    if (g.MATCH_COUNT > 0) {
      g.MATCH_COUNT = g.MATCH_COUNT - 1;
    }
    if (!(g.MATCH_COUNT > 0)) {
      tell("I'm afraid that you have run out of matches.\n");
      return true;
    } else if (g.HERE == LOWER_SHAFT || g.HERE == TIMBER_ROOM) {
      tell("This room is drafty, and the match goes out instantly.\n");
      return true;
    } else {
      setFlag(MATCH, FLAMEBIT);
      setFlag(MATCH, ONBIT);
      enable(await QUEUE(I_MATCH.id, 2));
      tell("One of the matches starts to burn.\n");
      if (!g.LIT) {
        g.LIT = true;
        await V_LOOK();
      }
      return true;
    }
  } else if (isVerb(V.LAMP_OFF) && hasFlag(MATCH, FLAMEBIT)) {
    tell("The match is out.\n");
    clearFlag(MATCH, FLAMEBIT);
    clearFlag(MATCH, ONBIT);
    g.LIT = await LIT$(g.HERE);
    if (!g.LIT) {
      tell("It's pitch black in here!\n");
    }
    await QUEUE(I_MATCH.id, 0);
    return true;
  } else if (isVerb(V.COUNT, V.OPEN)) {
    tell("You have ");
    cnt = g.MATCH_COUNT - 1;
    if (!(cnt > 0)) {
      tell("no");
    } else {
      tell(N(cnt));
    }
    tell(" match");
    if (!(cnt == 1)) {
      tell("es.");
    } else {
      tell(".");
    }
    return crlf();
  } else if (isVerb(V.EXAMINE)) {
    if (hasFlag(MATCH, ONBIT)) {
      tell("The match is burning.");
    } else {
      tell("The matchbook isn't very interesting, except for what's written on it.");
    }
    return crlf();
  } else {
    return false;
  }
}

