async function CANDLES_FCN() {
  if (!(hasFlag(CANDLES, TOUCHBIT))) {
    enable(await INT(I_CANDLES.id));
  }
  if (CANDLES == g.PRSI) {
    return false;
  } else {
    if (isVerb(V.LAMP_ON, V.BURN)) {
      if (hasFlag(CANDLES, RMUNGBIT)) {
        tell("Alas, there's not much left of the candles. Certainly not enough to burn.\n");
        return true;
      } else if (!g.PRSI) {
        if (hasFlag(MATCH, FLAMEBIT)) {
          tell("(with the match)\n");
          await PERFORM(V.LAMP_ON, CANDLES, MATCH);
          return true;
        } else {
          tell("You should say what to light them with.\n");
          return M_FATAL;
        }
      } else if ((g.PRSI == MATCH) && hasFlag(MATCH, ONBIT)) {
        tell("The candles are ");
        if (hasFlag(CANDLES, ONBIT)) {
          tell("already lit.\n");
          return true;
        } else {
          setFlag(CANDLES, ONBIT);
          tell("lit.\n");
          return enable(await INT(I_CANDLES.id));
        }
      } else if (g.PRSI == TORCH) {
        if (hasFlag(CANDLES, ONBIT)) {
          tell("You realize, just in time, that the candles are already lighted.\n");
          return true;
        } else {
          tell("The heat from the torch is so intense that the candles are vaporized.\n");
          return await REMOVE_CAREFULLY(CANDLES);
        }
      } else {
        tell("You have to light them with something that's burning, you know.\n");
        return true;
      }
    } else if (isVerb(V.COUNT)) {
      tell("Let's see, how many objects in a pair? Don't tell me, I'll get it.\n");
      return true;
    } else if (isVerb(V.LAMP_OFF)) {
      disable(await INT(I_CANDLES.id));
      if (hasFlag(CANDLES, ONBIT)) {
        tell("The flame is extinguished.");
        clearFlag(CANDLES, ONBIT);
        setFlag(CANDLES, TOUCHBIT);
        g.LIT = await LIT$(g.HERE);
        if (!g.LIT) {
          tell(" It's really dark in here....");
        }
        crlf();
        return true;
      } else {
        tell("The candles are not lighted.\n");
        return true;
      }
    } else if (isVerb(V.PUT) && hasFlag(g.PRSI, BURNBIT)) {
      tell("That wouldn't be smart.\n");
      return true;
    } else if (isVerb(V.EXAMINE)) {
      tell("The candles are ");
      if (hasFlag(CANDLES, ONBIT)) {
        tell("burning.");
      } else {
        tell("out.");
      }
      return crlf();
    } else {
      return false;
    }
  }
}

