async function ROPE_FUNCTION() {
  let rloc = 0;
  if (!(g.HERE == DOME_ROOM)) {
    g.DOME_FLAG = false;
    if (isVerb(V.TIE)) {
      tell("You can't tie the rope to that.\n");
      return true;
    } else {
      return false;
    }
  } else if (isVerb(V.TIE)) {
    if (g.PRSI == RAILING) {
      if (g.DOME_FLAG) {
        tell("The rope is already tied to it.\n");
        return true;
      } else {
        tell("The rope drops over the side and comes within ten feet of the floor.\n");
        g.DOME_FLAG = true;
        setFlag(ROPE, NDESCBIT);
        rloc = loc(ROPE);
        if (!rloc || !(loc(rloc) == ROOMS)) {
          move(ROPE, g.HERE);
        }
        return true;
      }
    } else {
      return false;
    }
  } else if (isVerb(V.CLIMB_DOWN) && (g.PRSO == ROPE || g.PRSO == ROOMS) && g.DOME_FLAG) {
    return await DO_WALK(P.DOWN);
  } else if (isVerb(V.TIE_UP) && (ROPE == g.PRSI)) {
    if (hasFlag(g.PRSO, ACTORBIT)) {
      if (getProp(g.PRSO, P.STRENGTH) < 0) {
        tell("Your attempt to tie up the ", D(g.PRSO), " awakens him.");
        return await AWAKEN(g.PRSO);
      } else {
        tell("The ", D(g.PRSO), " struggles and you cannot tie him up.\n");
        return true;
      }
    } else {
      tell("Why would you tie up a ", D(g.PRSO), "?\n");
      return true;
    }
  } else if (isVerb(V.UNTIE)) {
    if (g.DOME_FLAG) {
      g.DOME_FLAG = false;
      clearFlag(ROPE, NDESCBIT);
      tell("The rope is now untied.\n");
      return true;
    } else {
      tell("It is not tied to anything.\n");
      return true;
    }
  } else if (isVerb(V.DROP) && (g.HERE == DOME_ROOM) && !g.DOME_FLAG) {
    move(ROPE, TORCH_ROOM);
    tell("The rope drops gently to the floor below.\n");
    return true;
  } else if (isVerb(V.TAKE)) {
    if (g.DOME_FLAG) {
      tell("The rope is tied to the railing.\n");
      return true;
    } else {
      return false;
    }
  } else {
    return false;
  }
}

