async function DO_FIGHT(len) {
  let cnt = 0, res = 0, o = 0, oo = 0, out = false;
  for (;;) {
    cnt = 0;
    loop2: for (;;) {
      cnt = cnt + 1;
      if (cnt == len) {
        res = true;
        return true;
      }
      oo = get(g.VILLAINS, cnt);
      o = get(oo, V_VILLAIN);
      if (!(hasFlag(o, FIGHTBIT))) {
      } else if (await apply(getProp(o, P.ACTION), F_BUSY$)) {
      } else if (!(res = await VILLAIN_BLOW(oo, out))) {
        res = false;
        break loop2;
      } else if (res == UNCONSCIOUS) {
        out = 1 + random(3);
      }
    }
    if (res) {
      if (!out) {
        return true;
      } else {
        out = out - 1;
        if (out == 0) {
          return true;
        }
      }
    } else {
      return true;
    }
  }
}

async function REMARK(remark, d_, w_) {
  let len = get(remark, 0), cnt = 0, str = 0;
  loop1: for (;;) {
    if ((cnt = cnt + 1) > len) {
      break loop1;
    }
    str = get(remark, cnt);
    if (str == F_WEP) {
      printD(w_);
    } else if (str == F_DEF) {
      printD(d_);
    } else {
      printS(str);
    }
  }
  return crlf();
}

async function FIGHT_STRENGTH(adjust$ = true) {
  let s_ = 0;
  s_ = STRENGTH_MIN + div(g.SCORE, div(g.SCORE_MAX, STRENGTH_MAX - STRENGTH_MIN));
  if (adjust$) {
    return s_ + getProp(g.WINNER, P.STRENGTH);
  } else {
    return s_;
  }
}

async function VILLAIN_STRENGTH(oo) {
  let villain = get(oo, V_VILLAIN), od = 0, tmp = 0;
  od = getProp(villain, P.STRENGTH);
  if (!(od < 0)) {
    if ((villain == THIEF) && g.THIEF_ENGROSSED) {
      if (od > 2) {
        od = 2;
      }
      g.THIEF_ENGROSSED = false;
    }
    if (g.PRSI && hasFlag(g.PRSI, WEAPONBIT) && eq(get(oo, V_BEST), g.PRSI)) {
      tmp = od - get(oo, V_BEST_ADV);
      if (tmp < 1) {
        tmp = 1;
      }
      od = tmp;
    }
  }
  return od;
}

async function FIND_WEAPON(o) {
  let w_ = 0;
  w_ = first(o);
  if (!w_) {
    return false;
  }
  for (;;) {
    if ((w_ == STILETTO || w_ == AXE || w_ == SWORD) || (w_ == KNIFE || w_ == RUSTY_KNIFE)) {
      return w_;
    } else if (!(w_ = next(w_))) {
      return false;
    }
  }
}

async function VILLAIN_BLOW(oo, out$) {
  let villain = get(oo, V_VILLAIN), remarks = get(oo, V_MSGS), dweapon = 0, att = 0, def = 0, oa = 0, od = 0, tbl = 0, res = 0, nweapon = 0;
  clearFlag(g.WINNER, STAGGERED);
  if (hasFlag(villain, STAGGERED)) {
    tell("The ", D(villain), " slowly regains his feet.\n");
    clearFlag(villain, STAGGERED);
    return true;
  }
  oa = att = await VILLAIN_STRENGTH(oo);
  if (!((def = await FIGHT_STRENGTH()) > 0)) {
    return true;
  }
  od = await FIGHT_STRENGTH(false);
  dweapon = await FIND_WEAPON(g.WINNER);
  if (def < 0) {
    res = KILLED;
  } else {
    if (def == 1) {
      if (att > 2) {
        att = 3;
      }
      tbl = get(g.DEF1_RES, att - 1);
    } else if (def == 2) {
      if (att > 3) {
        att = 4;
      }
      tbl = get(g.DEF2_RES, att - 1);
    } else if (def > 2) {
      att = att - def;
      if (att < (-1)) {
        att = -2;
      } else if (att > 1) {
        att = 2;
      }
      tbl = get(g.DEF3_RES, att + 2);
    }
    res = get(tbl, random(9) - 1);
    if (out$) {
      if (res == STAGGER) {
        res = HESITATE;
      } else {
        res = SITTING_DUCK;
      }
    }
    if ((res == STAGGER) && dweapon && (await ZPROB(25))) {
      res = LOSE_WEAPON;
    }
    await REMARK(await RANDOM_ELEMENT(get(remarks, res - 1)), g.WINNER, dweapon);
  }
  if ((res == MISSED) || (res == HESITATE)) {
  } else if (res == UNCONSCIOUS) {
  } else if ((res == KILLED) || (res == SITTING_DUCK)) {
    def = 0;
  } else if (res == LIGHT_WOUND) {
    def = def - 1;
    if (def < 0) {
      def = 0;
    }
    if (g.LOAD_ALLOWED > 50) {
      g.LOAD_ALLOWED = g.LOAD_ALLOWED - 10;
    }
  } else if (res == SERIOUS_WOUND) {
    def = def - 2;
    if (def < 0) {
      def = 0;
    }
    if (g.LOAD_ALLOWED > 50) {
      g.LOAD_ALLOWED = g.LOAD_ALLOWED - 20;
    }
  } else if (res == STAGGER) {
    setFlag(g.WINNER, STAGGERED);
  } else {
    move(dweapon, g.HERE);
    if (nweapon = await FIND_WEAPON(g.WINNER)) {
      tell("Fortunately, you still have a ", D(nweapon), ".\n");
    }
  }
  return await WINNER_RESULT(def, res, od);
}

