async function ROB(what, where, prob_ = false) {
  let n_ = 0, x = 0, robbed$ = false;
  x = first(what);
  for (;;) {
    if (!x) {
      return robbed$;
    }
    n_ = next(x);
    if (!(hasFlag(x, INVISIBLE)) && !(hasFlag(x, SACREDBIT)) && (getProp(x, P.TVALUE) > 0) && (!prob_ || (prob_ > random(100)))) {
      move(x, where);
      setFlag(x, TOUCHBIT);
      if (where == THIEF) {
        setFlag(x, INVISIBLE);
      }
      robbed$ = true;
    }
    x = n_;
  }
}

